// Des: Tests for ru-appr-list: item parse, risk class, approval once, ids, packing
// Flo: texts > parsed items > saved flow > approve > list text
// I/O: texts and memory store > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const appr = @import("ru-appr-list.zig"); const data = @import("st-stat-data.zig"); const flo = @import("st-flow-data.zig"); const T = std.testing;
test "job words and plain phrases parse; junk and empty are BadJob" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); const one = try appr.parseItem(alo, "send Mom see you at 7"); try T.expectEqualStrings("send", one.job); try T.expectEqual(@as(usize, 5), one.args.len); const two = try appr.parseItem(alo, "remind Mom at 8 to buy milk"); try T.expectEqualStrings("say", two.job); try T.expectEqualStrings("remind Mom at 8 to buy milk", two.args[0]); const two2 = try appr.parseItem(alo, "remind Mom 20:00 call back"); try T.expectEqualStrings("remind", two2.job); try T.expectEqual(@as(usize, 4), two2.args.len); const three = try appr.parseItem(alo, "summarize unread"); try T.expectEqualStrings("say", three.job); try T.expectEqualStrings("summarize unread", three.args[0]); const four = try appr.parseItem(alo, "say send Mom: hi"); try T.expectEqualStrings("say", four.job); try T.expectEqualStrings("send Mom: hi", four.args[0]); try T.expectError(error.BadJob, appr.parseItem(alo, "dance now")); try T.expectError(error.BadJob, appr.parseItem(alo, "   ")); }
test "risk: group and forward ask, everything else is low" { try T.expectEqualStrings("ask", appr.riskOf("group")); try T.expectEqualStrings("ask", appr.riskOf("forward")); try T.expectEqualStrings("low", appr.riskOf("send")); try T.expectEqualStrings("low", appr.riskOf("read")); try T.expectEqualStrings("ask", appr.riskOf("recall")); try T.expectEqualStrings("ask", appr.riskOf("friend")); try T.expectEqualStrings("ask", appr.riskOf("leave")); try T.expectEqualStrings("low", appr.riskOf("react")); try T.expectEqualStrings("low", appr.riskOf("nonsense")); }
test "pack and unpack keep spaces and empty lists" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); const words = [_][]const u8{ "Mom", "two words", "x" }; const back = try appr.unpack(alo, try appr.pack(alo, &words)); try T.expectEqual(@as(usize, 3), back.len); try T.expectEqualStrings("two words", back[1]); try T.expectEqual(@as(usize, 0), (try appr.unpack(alo, "")).len); }
test "plan saves items in order, only ask items need approval, list text says so" { var sto = try data.Stor.open(T.allocator, ":memory:"); defer sto.close(); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); const items = [_][]const u8{ "read", "group Family", "send Mom hi" }; const fl = try appr.planFlow(&sto, alo, "u1", "t", &items, 5); const its = try flo.itemsOf(&sto, alo, fl); try T.expectEqual(@as(usize, 3), its.len); try T.expect(its[0].appr and !its[1].appr and its[2].appr); const txt = try appr.render(&sto, alo, fl); try T.expect(std.mem.find(u8, txt, "[NEEDS APPROVAL] group Family") != null); try T.expect(std.mem.find(u8, txt, "1 item(s) need approval") != null); try T.expectError(error.BadJob, appr.planFlow(&sto, alo, "u2", "t", &.{}, 5)); try T.expectError(error.BadJob, appr.planFlow(&sto, alo, "u3", "t", &.{ "read", "dance" }, 5)); const lat = (try flo.flowLatest(&sto, alo)).?; try T.expectEqual(fl, lat.id); }
test "approve all and approve by ids are once-only; foreign ids are refused" { var sto = try data.Stor.open(T.allocator, ":memory:"); defer sto.close(); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); const fl = try appr.planFlow(&sto, alo, "u", "t", &.{ "group A", "forward Mom Boss", "group B" }, 1); const its = try flo.itemsOf(&sto, alo, fl); const first = try std.fmt.allocPrint(alo, "{d}", .{its[0].id}); try T.expectEqual(@as(u32, 1), try appr.approve(&sto, alo, fl, first)); try T.expectEqual(@as(u32, 0), try appr.approve(&sto, alo, fl, first)); try T.expectEqual(@as(u32, 2), try appr.approve(&sto, alo, fl, "ALL")); try T.expectEqual(@as(u32, 0), try appr.approve(&sto, alo, fl, "all")); try T.expectError(error.BadJob, appr.approve(&sto, alo, fl, "999")); try T.expectError(error.BadJob, appr.approve(&sto, alo, fl, "x")); try T.expectError(error.BadJob, appr.approve(&sto, alo, fl, "")); const txt = try appr.render(&sto, alo, fl); try T.expect(std.mem.find(u8, txt, "nothing needs approval") != null); }
test "ids parse commas and spaces, reject zero and negatives" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const ids = try appr.parseIds(aren.allocator(), "3, 5,7"); try T.expectEqual(@as(usize, 3), ids.len); try T.expectEqual(@as(i64, 5), ids[1]); try T.expectError(error.BadJob, appr.parseIds(aren.allocator(), "0")); try T.expectError(error.BadJob, appr.parseIds(aren.allocator(), "-2")); }
